window.REPORT_PRELOAD_CACHE["UEC.html"] = {"version":"d4fa5f31bce1e5abee29312e49168c872446afd5c2fedbbc046c52d787d7b641","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>铀能公司 Uranium Energy Corp. (NYSE: UEC) 深度商业与投资价值分析报告</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n uraniumgreen: {\n 350: '#4ADE80',\n 400: '#22C55E',\n 500: '#16A34A',\n 600: '#15803D',\n 700: '#166534',\n },\n uraniumblue: {\n 400: '#38BDF8',\n 500: '#0EA5E9',\n 600: '#0284C7',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar { width: 6px; height: 6px; }\n ::-webkit-scrollbar-track { background: transparent; }\n ::-webkit-scrollbar-thumb { background: #94A3B8; border-radius: 3px; }\n .dark ::-webkit-scrollbar-thumb { background: #475569; }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print { display: none !important; }\n main { margin-left: 0 !important; padding: 0 !important; }\n section { break-inside: avoid; }\n }\n\n .report-card { transition: transform 0.2s ease, box-shadow 0.2s ease; }\n .report-card:hover { transform: translateY(-2px); }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(34, 197, 94, 0.22) 0%, rgba(14, 165, 233, 0.05) 100%);\n border-left: 3px solid #22C55E;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-uraniumgreen-500 selection:text-white transition-colors duration-200\">\n\n <!-- 全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-uraniumgreen-600 via-uraniumgreen-400 to-uraniumblue-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-uraniumgreen-600 to-navy-900 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n UEC\n </div>\n <div>\n <div class=\"text-[11px] text-uraniumgreen-300 font-semibold tracking-wider uppercase\">NYSE American: UEC · Nuclear Energy</div>\n <div class=\"text-sm font-bold leading-tight\">铀能公司深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 text-slate-300\" aria-label=\"主题切换\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 text-white\" aria-label=\"菜单\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端抽屉 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">UEC 研报目录</span>\n <button onclick=\"toggleMobileMenu()\" class=\"text-slate-400 hover:text-white\">✕</button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">00. 执行摘要与最新进展</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">01. 商业模式与 ISR 采矿技术</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">02. 核心竞争优势与零债务资产负债表</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">03. 财务与生产运营表现</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">04. 行业宏观与核能复兴周期</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">05. 估值展望与投资策略</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">06. 跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>美股铀矿与核能能源研究组</p>\n <p class=\"mt-1\">数据基准：2026年最新财报与市场行情</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧边栏 (280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-uraniumgreen-600 to-navy-900 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-uraniumgreen-600/25\">\n UEC\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-uraniumgreen-300 bg-uraniumgreen-500/15 px-2 py-0.5 rounded\">NYSE American: UEC</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">铀能公司研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 美 国 领 先 的 纯 铀 采 矿 与 地 方 产 能 巨 头 · 拥 有 德 克 萨 斯 与 怀 俄 明 ISR 铀 矿 及 巨 额 流 动 性 资 产\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (2026年尾)</span>\n <span class=\"font-mono font-bold text-white\">~$7.62 - $8.04</span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">流动性资产（无债务）</span>\n <span class=\"font-mono font-bold text-emerald-400\">~$7.94 亿美元</span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">实物铀库存 (库存持仓)</span>\n <span class=\"font-mono font-bold text-uraniumgreen-300\">146 万磅未套期保值</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">报告核心章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-uraniumgreen-400 mr-2\">00</span>执行摘要与最新进展</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式与 ISR 采矿技术</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>核心优势与零债务资产负债表</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>财务与生产运营表现</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>行业宏观与核能复兴周期</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>估值展望与投资策略</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">页面显示模式</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-uraniumgreen-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-uraniumgreen-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色模式</span>\n <span class=\"hidden dark:inline\">浅色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-uraniumgreen-600 to-uraniumgreen-700 hover:from-uraniumgreen-700 text-white text-xs font-extrabold transition cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span class=\"text-white\">打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. 封面与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-uraniumgreen-500/15 text-uraniumgreen-700 dark:text-uraniumgreen-300 font-bold border border-uraniumgreen-500/30\">机构评级：审慎乐观 / 买入潜力</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">覆盖基准：2026年最新运营与核能市场周期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>股票代码：NYSE American: UEC</span>\n <span>资产亮点：$7.94亿流动性资产·零负债</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#22C55E 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-uraniumgreen-500/20 border border-uraniumgreen-400/40 text-uraniumgreen-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-uraniumgreen-400 animate-pulse\"></span>\n <span>EXECUTIVE SUMMARY · Burke Hollow投产与产量飙升 157% × $7.94亿堡垒级资产负债表 × 100%未套期保值全价暴露</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 铀能公司 Uranium Energy Corp. (NYSE American: UEC) 深度商业与投资价值分析报告\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 铀能公司（Uranium Energy Corp., 代码：<strong class=\"text-white\">UEC</strong>）作为美国本土领先的纯铀矿开采与开发企业，在 2026 年迎来了关键的产能爆发与战略兑现期。公司拥有德克萨斯州和怀俄明州世界级的地浸采矿（ISR）产能平台，近期季度铀产量环比大幅飙升 <strong class=\"text-uraniumgreen-300\">157%</strong>（达 82,744 磅），总现金成本显著下降 33% 至 $30.01/磅 [cite: 1.2.4]。\n 凭借 <strong class=\"text-emerald-400\">约 7.94 亿美元的充沛流动性资产、零长期债务</strong>以及 146 万磅 100% 未套期保值的实物铀库存，UEC 完美契合美国核能独立自主与 AI 数据中心拉动的大规模核能复兴红利 [cite: 1.1.3]。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">产能大幅爬坡放量</div>\n <div class=\"text-white font-semibold\">结合德州与怀俄明州 ISR 设施，最新季度产量跃升 157% 至 82,744 磅，现金成本降至 $30.01/磅 [cite: 1.2.4]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">堡垒级零债务资产负债表</div>\n <div class=\"text-uraniumgreen-300 font-semibold\">持有约 $7.94 亿美元现金、实物库存及战略股权投资，零债务，抗风险能力极强 [cite: 1.1.3]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">100% 未套期保值全弹性</div>\n <div class=\"text-emerald-400 font-semibold\">坐拥 146 万磅物理铀库存，未锁定长协价格，全面享受铀价上行带来的巨大弹性 [cite: 1.1.3]</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 四大核心 KPI 指标卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>流动性与总资产储备</span>\n <span class=\"p-1.5 rounded-lg bg-uraniumgreen-500/15 text-uraniumgreen-600 dark:text-uraniumgreen-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$7.94亿</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">零债务 · 极强防御</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 拥有约 4.88 亿现金、1.27 亿实物铀库存以及 1.79 亿战略股权，无任何债务负担 [cite: 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>季度铀产量飙升幅度</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">+157%</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">达 82,744 磅</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 随着德州 Burke Hollow 首个完整季度投产及怀俄明州产能恢复，季度产量环比大幅飙升 157% [cite: 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总现金成本 (Cash Cost/lb)</span>\n <span class=\"p-1.5 rounded-lg bg-uraniumblue-500/15 text-uraniumblue-600 dark:text-uraniumblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$30.01</span>\n <span class=\"text-xs font-bold text-uraniumblue-600 dark:text-uraniumblue-400 bg-uraniumblue-500/15 px-2 py-0.5 rounded\">成本大幅下降 33%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 随着规模效应释放，每磅现金生产成本显著下降至 $30.01（总成本 $36.54），相比现货铀价拥有极宽的利润空间 [cite: 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>实物铀库存 (U₃O₈)</span>\n <span class=\"p-1.5 rounded-lg bg-uraniumgreen-500/15 text-uraniumgreen-600 dark:text-uraniumgreen-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">146万磅</span>\n <span class=\"text-xs font-bold text-uraniumgreen-700 dark:text-uraniumgreen-300 bg-uraniumgreen-500/15 px-2 py-0.5 rounded\">战略物理储备</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 持有 146 万磅战略采购的实物铀库存，完全未做套期保值，作为平衡资产负债与捕捉现货暴涨的王牌 [cite: 1.1.2, 1.1.3]。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 商业模式与 ISR 采矿技术\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uraniumgreen-600 dark:text-uraniumgreen-400\">Section 01 · Business Model & ISR Technology</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式与 ISR 地浸采矿技术：低成本、环保与 Hub-and-Spoke 枢纽模式</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">核心工艺：In-Situ Recovery (ISR) 地浸开采</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">UEC 核心资产与 Hub-and-Spoke 枢纽加工架构</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">德克萨斯州 Hobson 与怀俄明州 Irigaray 中央处理厂（CPP）枢纽分布</p>\n </div>\n <span class=\"px-2.5 py-1 rounded bg-uraniumgreen-500/15 text-uraniumgreen-600 dark:text-uraniumgreen-400 text-xs font-bold\">美国本土 ISR 龙头</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizAssetsChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业模式三大核心支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-uraniumgreen-500/15 text-uraniumgreen-600 dark:text-uraniumgreen-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">ISR 地浸采矿技术优势</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 采用环保且高效的原地浸出（ISR）技术，不产生传统露天或地下开采的大量废石尾矿，资本开支极低且现金生产成本远低于全球传统矿山平均水平。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-uraniumblue-500/15 text-uraniumblue-600 dark:text-uraniumblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Hub-and-Spoke 集中处理枢纽架构</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 以德克萨斯州 Hobson 和怀俄明州 Irigaray 两大完全持牌的中央处理厂（CPP）为核心枢纽，汇聚周边卫星矿山（如 Burke Hollow 和 Christensen Ranch）的产出，实现规模效益最大化 [cite: 1.1.2]。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">多项目储备与地缘战略布局</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 除了美本土 ISR 项目外，还拥有加拿大大型常规铀矿项目（如 Roughrider 正在推进预可行性研究 PFS）以及南美稀土/钛钒项目，资产组合极具深度 [cite: 1.1.1]。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">战略定位</span>\n <span class=\"font-bold text-uraniumgreen-600 dark:text-uraniumgreen-400\">全美稀缺的完全许可、可立即扩产的铀企</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 核心竞争优势与零债务资产负债表\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Core Advantages & Financial Fortitude</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 核心竞争优势与零债务资产负债表：100% 价格暴露与政策红利</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 美本土铀供应标杆)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-uraniumgreen-500/15 text-uraniumgreen-600 dark:text-uraniumgreen-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">堡垒级无债务财务结构（$7.94亿流动性）</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有约 4.88 亿现金、1.27 亿实物铀及 1.79 亿战略股权，零长期债务。这使其能够在不进行股权稀释的前提下，从容推进 Burke Hollow、Christensen Ranch 等项目的并行开发 [cite: 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">100% 未套期保值（Full Price Exposure）</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 坚持完全未锁定长协价格的策略，坐拥 146 万磅物理库存。当铀现货价格由于供给短缺出现暴涨时，每一美元的涨幅都能直接转化为股东价值 [cite: 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-uraniumblue-500/15 text-uraniumblue-600 dark:text-uraniumblue-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">美国本土供应政策与核能法案红利</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 美国作为全球最大核能消费国，高度依赖本土及无地缘风险的铀原料与转化服务。UEC 作为美本土最大、许可最齐全的铀矿商，受益于《核燃料安全法案》及政府去俄化供应链政策 [cite: 1.2.3, 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">垂直一体化供应链布局</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 从铀矿开采、ISR 提取、中央处理到参与美国本土铀转化厂 shortlist 评估，UEC 正在打造独特的全产业链解决方案 [cite: 1.1.1, 1.2.4]。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">铀矿采掘行业五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">UEC (Uranium Energy) vs 传统铀矿企业综合评估（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 财务与生产运营表现\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uraniumgreen-600 dark:text-uraniumgreen-400\">Section 03 . Financial & Operational Performance</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 财务与生产运营表现：产量飙升 157% 与成本优势显现</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">单季度产量 82,744 磅 · 现金成本降至 $30.01/磅 [cite: 1.2.4]</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-uraniumgreen-600 dark:text-uraniumgreen-400 uppercase\">Q4 Production Volume</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">82,744 磅</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 单季度合并产出 precipitated 铀总量达到 82,744 磅（环比大幅增长 157%），产能爬坡进入快车道 [cite: 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Total Cash Cost / lb</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$30.01</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 随着产能规模扩大，每磅现金生产成本下降 33% 至 $30.01（总成本 $36.54），构筑极强的成本安全垫 [cite: 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-uraniumblue-600 dark:text-uraniumblue-400 uppercase\">Liquid Assets</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$7.94亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 截至最新报告期，公司拥有 7.94 亿美元的高流动性资产储备，为全面扩张提供充足弹药 [cite: 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Total Resources</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">3.3亿磅</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 在美洲（美国、加拿大、巴拉圭）拥有约 3.3 亿磅 U₃O₈ 的庞大矿产资源储量，长远战略价值极为凸显 [cite: 1.2.3]。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">UEC 季度铀产量爬坡与现金成本走势演进</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">产量逐季跳升，规模效应带动单位现金成本持续下行</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-uraniumgreen-700 dark:text-uraniumgreen-300 bg-uraniumgreen-500/15 px-2.5 py-1 rounded\">产能释放与成本优化</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"finTrendChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 行业宏观与核能复兴周期\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uraniumgreen-600 dark:text-uraniumgreen-400\">Section 04 · Macro Industry & Nuclear Renaissance</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 行业宏观与核能复兴周期：AI 数据中心电力荒与 17 亿磅历史供需缺口</h2>\n </div>\n <div class=\"flex items-center space-x-2 text-xs text-slate-500 dark:text-slate-400\">\n <span>全球核能装机目标翻番 · 铀供给面临长期结构性赤字</span>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-uraniumgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-uraniumgreen-500/15 text-uraniumgreen-700 dark:text-uraniumgreen-300 text-xs font-bold\">需求催化剂 · AI 数据中心</span>\n <span class=\"font-mono text-xs font-bold text-uraniumgreen-600 dark:text-uraniumgreen-400\">电力需求激增</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">科技巨头竞逐核电基载</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n 随着人工智能（AI）与量子计算数据中心对 24/7 不间断清洁基载电力需求呈爆发式增长，科技巨头与美政府正全力推动核能复兴，将美国核能发电目标在未来 25 年内翻两番 [cite: 1.2.4, 1.2.5]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-uraniumgreen-600 dark:text-uraniumgreen-400\">\n 美国电力需求预计到 2028 年大幅攀升 [cite: 1.2.4]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-uraniumblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-uraniumblue-500/15 text-uraniumblue-700 dark:text-uraniumblue-300 text-xs font-bold\">供给缺口 · 17亿磅赤字</span>\n <span class=\"font-mono font-bold text-xs text-uraniumblue-600 dark:text-uraniumblue-400\">长期结构性短缺</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">2026-2045年供需失衡</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n 行业模型预测，2026年至 2045 年全球将累计面临超过 16亿 至 17 亿磅的铀矿供给缺口。由于过去十年长期低价导致矿山投资不足，原生矿产能远无法跟上激增的反应堆需求 [cite: 1.2.4, 1.2.5]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-uraniumblue-600 dark:text-uraniumblue-400\">\n 累计供需缺口高达 17 亿磅 [cite: 1.2.4]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">地缘安全 · 去俄化与国防法案</span>\n <span class=\"font-mono font-bold text-xs text-indigo-600 dark:text-indigo-400\">美国本土溢价</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">国防生产法与本土优先</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n 美国政府通过《国防生产法》及核燃料安全法案，大力扶持本土铀矿采掘与转化能力，减少对俄罗斯等海外进口的依赖，为 UEC 等本土企业带来极其宝贵的政策护城河 [cite: 1.2.4, 1.2.5]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-indigo-600 dark:text-indigo-400\">\n 确保无地缘风险的美国本土铀供应 [cite: 1.2.4]\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 估值展望与投资策略\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uraniumgreen-600 dark:text-uraniumgreen-400\">Section 05 · Valuation Outlook & Investment Strategy</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 估值展望与投资策略：华尔街目标价锚定 $16+ 与长线配置价值</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">机构一致目标价中枢 ~$16.03 [cite: 1.2.3]</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">乐观情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">目标价：$20 – $25+</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">铀现货价格突破 $150/磅</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>随着 AI 电力荒与全球核电重启引发铀现货价格飙升至 $150/磅，UEC 凭借 100% 未套期保值的 146 万磅库存与全美放量产能，业绩与估值将迎来戴维斯双击 [cite: 1.1.3, 1.2.1]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 享受铀价暴涨带来的超额弹性收益 [cite: 1.1.3]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-uraniumgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-uraniumgreen-500/15 text-uraniumgreen-700 dark:text-uraniumgreen-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-uraniumgreen-600 dark:text-uraniumgreen-400\">目标价：$15 – $17</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">华尔街共识目标价 ~$16.03</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>公司稳步推进 Burke Hollow 等矿山的产能爬坡，零债务与近 8 亿美元流动性提供强力安全垫，估值向行业分析师中位目标价稳步靠拢 [cite: 1.1.3, 1.2.3, 1.2.4]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-uraniumgreen-600 dark:text-uraniumgreen-400\">\n 机构平均目标价约 $16.03 [cite: 1.2.3]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">谨慎情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">目标价：$5.50 – $6.50</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">宏观震荡与铀价回调</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>若宏观经济出现系统性衰退导致能源需求短期放缓，或铀现货市场陷入盘整，无营收期间将承受 mark-to-market 资产账面波动压力 [cite: 1.1.3]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 需密切跟踪铀现货价格波动与产能落地速度\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-uraniumgreen-300 mb-3 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构投资策略建议</span>\n </h3>\n <p class=\"text-xs sm:text-sm text-slate-300 leading-relaxed\">\n 铀能公司 (UEC) 作为美股稀缺的纯铀矿开发与产能标的，具备“零债务 + 高流动性 + 100% 未套期保值库存”的完美组合 [cite: 1.1.3]。在核能复兴与结构性供需缺口的大背景下，建议投资者将其作为把握核能超级周期的高弹性核心配置标的 [cite: 1.2.4]。\n </p>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 跟踪 KPI 核查清单\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Regular Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六 / 定期跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-uraniumgreen-500/15 text-uraniumgreen-700 dark:text-uraniumgreen-300 text-xs font-bold\">已核查 3 / 5 项 (60%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选 UEC 投资组合监控中的关键运营指标（本地状态自动保存）：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#22C55E]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 德州 Burke Hollow 及怀俄明州产能持续爬坡放量</span>\n <span class=\"text-[11px] font-mono text-uraniumgreen-600 dark:text-uraniumgreen-400 font-semibold shrink-0\">核心产能指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控季度铀产量是否保持环比上升（如最新季度达到 82,744 磅），确保 ISR 项目顺利放量 [cite: 1.2.4]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#22C55E]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 保持零债务与 ~$7.94 亿的高流动性资产充沛</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">财务安全边际</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认资产负债表维持无长期债务结构，现金及实物库存储备足以支撑长期战略发展 [cite: 1.1.3]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#22C55E]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 单位现金生产成本保持在行业极具竞争力的低位</span>\n <span class=\"text-[11px] font-mono text-uraniumblue-600 dark:text-uraniumblue-400 font-semibold shrink-0\">成本控制能力</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 验证每磅现金成本（如 $30.01/lb）是否随着规模效应进一步优化，维持高毛利弹性 [cite: 1.2.4]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#22C55E]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 146 万磅实物铀库存未做套期保值，充分享受价格弹性</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">价格暴露策略</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认未提前锁定长协，实物库存随时准备在现货铀价高点兑现超额收益 [cite: 1.1.3]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#22C55E]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 积极推进 Roughrider 等项目及本土转化厂布局</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">长期战略成长</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪 Roughrider 预可行性研究进展及美国本土铀转化厂候选名单的最终落地情况 [cite: 1.1.1]。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>铀能公司 Uranium Energy Corp. (NYSE American: UEC) 深度商业与投资价值分析报告 [cite: 1.2.3]</span>\n <span>数据基准：2026 年最新财报与核能行业公开披露 [cite: 1.2.1, 1.2.4]</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本报告基于 UEC 公开披露的财报、SEC 申报文件及核能行业研究数据撰写，旨在提供结构化商业研究参考。报告中的前瞻性预测、目标价及财务推演不构成任何直接证券投资建议。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-uraniumgreen-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-uraniumgreen-400');\n }\n }\n });\n });\n\n const KPI_STORAGE_KEY = 'uec_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizAssetsChartInstance = null;\n let moatRadarChartInstance = null;\n let finTrendChartInstance = null;\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizAssetsChart() {\n const ctx = document.getElementById('bizAssetsChart').getContext('2d');\n const colors = getChartColors();\n\n if (bizAssetsChartInstance) bizAssetsChartInstance.destroy();\n bizAssetsChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['德州 Burke Hollow (ISR项目)', '德州 Hobson 中央处理厂 (CPP)', '怀俄明州 Christensen Ranch (ISR)', '怀俄明州 Irigaray 中央处理厂', '加拿大 Roughrider (常规铀矿)'],\n datasets: [\n {\n label: '核心资产战略权重占比估算 (%)',\n data: [30, 20, 25, 15, 10],\n backgroundColor: '#22C55E',\n borderRadius: 6,\n barThickness: 22\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `资产战略权重约: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 40,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initMoatRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (moatRadarChartInstance) moatRadarChartInstance.destroy();\n moatRadarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '无债务资产负债表与高流动性 ($7.94亿)',\n '100% 未套期保值实物铀库存 (146万磅)',\n '美国本土 ISR 许可与政策红利',\n 'Hub-and-Spoke 低成本生产架构',\n '3.3亿磅海量矿产资源储量储备'\n ],\n datasets: [\n {\n label: 'UEC (铀能公司)',\n data: [9.9, 9.8, 9.7, 9.5, 9.6],\n borderColor: '#22C55E',\n backgroundColor: 'rgba(34, 197, 94, 0.22)',\n pointBackgroundColor: '#22C55E',\n borderWidth: 2.5\n },\n {\n label: '行业平均水平',\n data: [7.2, 7.0, 7.5, 7.8, 8.0],\n borderColor: '#0EA5E9',\n backgroundColor: 'rgba(14, 165, 233, 0.12)',\n pointBackgroundColor: '#0EA5E9',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initFinTrendChart() {\n const ctx = document.getElementById('finTrendChart').getContext('2d');\n const colors = getChartColors();\n\n if (finTrendChartInstance) finTrendChartInstance.destroy();\n finTrendChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026 (最新爬坡期)'],\n datasets: [\n {\n type: 'bar',\n label: '年化铀产量量级 (千磅 k lbs)',\n data: [120, 210, 310, 450],\n backgroundColor: 'rgba(34, 197, 94, 0.85)',\n borderRadius: 6,\n barThickness: 32,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '现金生产成本 Cash Cost ($/lb)',\n data: [38.5, 35.0, 32.4, 30.0],\n borderColor: '#0EA5E9',\n backgroundColor: '#0EA5E9',\n borderWidth: 3,\n pointRadius: 5,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 600,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + 'k lbs' },\n title: { display: true, text: '年化铀产量 (千磅)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 50,\n grid: { drawOnChartArea: false },\n ticks: { color: '#0EA5E9', font: { size: 11, weight: '600' }, callback: v => '$' + v },\n title: { display: true, text: '现金成本 ($/lb)', color: '#0EA5E9', font: { size: 11 } }\n },\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizAssetsChart();\n initMoatRadarChart();\n initFinTrendChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizAssetsChart();\n initMoatRadarChart();\n initFinTrendChart();\n });\n </script>\n</body>\n</html>\n"};
